mapper.update:
UPDATE train_segment_stock tss
INNER JOIN train_station ts ON tss.train_id = ts.train_id AND tss.start_station_id = ts.station_id
SET tss.stock = tss.stock - 1,
    tss.update_time = NOW()
WHERE tss.train_id = #{trainId}
  AND tss.travel_date = #{departureDate}
  AND tss.seat_type = #{seatType}
  AND ts.station_index >= #{startIndex}
  AND ts.station_index < #{endIndex}
  AND tss.stock > 0

mapper.select:
SELECT COUNT(*) = SUM(CASE WHEN tss.stock > 0 THEN 1 ELSE 0 END)
FROM train_segment_stock tss
INNER JOIN train_station ts ON tss.train_id = ts.train_id AND tss.start_station_id = ts.station_id
WHERE tss.train_id = #{trainId}
  AND tss.travel_date = #{departureDate}
  AND tss.seat_type = #{seatType}
  AND ts.station_index >= #{startIndex}
  AND ts.station_index < #{endIndex}

mapper.update:
UPDATE train_segment_stock tss
INNER JOIN train_station ts ON tss.train_id = ts.train_id AND tss.start_station_id = ts.station_id
SET tss.stock = tss.stock + 1,
    tss.update_time = NOW()
WHERE tss.train_id = #{trainId}
  AND tss.travel_date = #{departureDate}
  AND tss.seat_type = #{seatType}
  AND ts.station_index >= #{startIndex}
  AND ts.station_index < #{endIndex}
